<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; if(isset($_SESSION['user_id'])){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $username=trim($_POST['username']??'');$password=$_POST['password']??''; try{$q=db()->prepare('SELECT id,username,password_hash,role,active FROM users WHERE username=? LIMIT 1');$q->execute([$username]);$u=$q->fetch(); if($u && (int)$u['active']===1 && password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['username']=$u['username'];$_SESSION['role']=$u['role'];header('Location: index.php');exit;} $error='Invalid username or password.';}catch(Throwable $e){$error='Login failed: '.$e->getMessage();}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · <?=e(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>body{min-height:100vh;display:grid;place-items:center}.login{width:min(420px,92vw)}.login .panel{padding:30px}.login h1{margin:6px 0}.login input{width:100%;box-sizing:border-box;margin:7px 0 14px}.login .btn{width:100%;margin-top:8px}.login-brand{text-align:center;font-size:24px;font-weight:800;margin-bottom:20px}.login-note{text-align:center;color:#64748b;font-size:12px;margin-top:14px}</style></head><body><div class="login"><div class="login-brand">💊 <?=e(APP_NAME)?></div><section class="panel"><div class="eyebrow">STAFF LOGIN</div><h1>Welcome back</h1><p>Sign in to use the pharmacy POS.</p><?php if($error):?><div class="alert">⚠ <?=e($error)?></div><?php endif;?><form method="post"><label>Username<input name="username" autocomplete="username" autofocus required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="btn" type="submit">Sign In →</button></form></section><div class="login-note">Use the account created in Management → Users.</div></div></body></html>